using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CursedPredictionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/CursedPredictionCustomDescription", order = 0)]
public class CursedPredictionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CursedPredictionAction obj = battleAction as CursedPredictionAction;
		string actionDescription = obj.PrecisionAction.GetActionDescription(EffectsValues.NO_VALUE);
		string actionDescription2 = obj.HexAction.GetActionDescription(GetAmountWithoutEquation(amountModified));
		return actionDescription + "\n" + actionDescription2;
	}
}
